import { describe, expect, it } from 'vitest'
import { ECUS } from '#shared/utils/ecus'
import adaptersData from '../data/openecu/adapters.json'
import { getAdapter } from '../server/utils/ecus'

// Guards data/openecu/adapters.json, which nothing else checks: it is generated by
// scripts/sync-adapters.ts (a file no tsconfig includes, so typecheck never sees it) and read
// through a cast in server/utils/ecus.ts. Before these tests the only thing standing between a
// degraded regeneration and production was a CI=1 build, and a shortfall short of zero channels
// would have passed that too — the channel section is rendered behind
// `v-if="data?.channels.length"`, so it vanishes rather than looking broken.

const adapterRefs = ECUS.map((e) => e.oecua).filter((r): r is string => !!r)

/**
 * Channel counts as of UltraLog 81b87de. A change here is fine — it just has to be deliberate.
 * Update the numbers in the same commit as the regenerated JSON.
 */
const EXPECTED: Record<string, number> = {
  'aim/aim-xrk': 47,
  'ecumaster/ecumaster-emu-csv': 33,
  'emerald/emerald-lg': 32,
  'haltech/haltech-nsp': 37,
  'link/link-llg': 57,
  'megasquirt/megasquirt-tunerstudio': 21,
  'romraider/romraider-csv': 95,
  'rusefi/rusefi-mlg': 133,
  'speeduino/speeduino-mlg': 92,
}

describe('openecu adapter data', () => {
  it('covers every adapter the ECU list names, and nothing it does not', () => {
    expect([...adapterRefs].sort()).toEqual(Object.keys(adaptersData.adapters).sort())
    expect([...adapterRefs].sort()).toEqual(Object.keys(EXPECTED).sort())
  })

  it('records where it came from', () => {
    const { repo, ref, corpus } = adaptersData.source
    expect(repo).toBe('ClassicMiniDIY/UltraLog')
    expect(corpus).toBe('spec/openecu/adapters')
    expect(ref).toBeTruthy()
    // A dirty local tree is fine to develop against but must not be what ships.
    expect(ref).not.toMatch(/-dirty$/)
  })

  it.each(adapterRefs)('%s resolves with complete metadata', (ref) => {
    const got = getAdapter(ref)
    expect(got).not.toBeNull()
    for (const field of ['id', 'name', 'version'] as const) {
      expect(got!.adapter[field], `${ref}.${field}`).toBeTruthy()
    }
    expect(got!.adapter.url).toContain(`${ref}.adapter.yaml`)
  })

  it.each(Object.entries(EXPECTED))('%s has %i channels', (ref, count) => {
    expect(getAdapter(ref)!.channels).toHaveLength(count)
  })

  it('leaves no channel without a name or source names', () => {
    const broken: string[] = []
    for (const ref of adapterRefs) {
      for (const c of getAdapter(ref)!.channels) {
        if (!c.name) broken.push(`${ref}: a channel has no name`)
        // The spec is snake_case (`source_names`); the retired REST API served the same data
        // camelCased. Reading the YAML with the API's shape empties every one of these and
        // raises nothing, so this is the assertion that catches that regression.
        if (c.sourceNames.length === 0) broken.push(`${ref}: ${c.name} has no source names`)
      }
    }
    expect(broken).toEqual([])
  })

  it('throws, rather than degrading, when an adapter is missing', () => {
    expect(() => getAdapter('nosuch/adapter')).toThrow(/no adapter "nosuch\/adapter"/)
  })

  it('maps kph, which 18 channels use and the unit table used to miss', () => {
    const speeds = getAdapter('rusefi/rusefi-mlg')!.channels.filter((c) => c.unit === 'km/h')
    expect(speeds.length).toBeGreaterThan(0)
    // Nothing should still be showing the raw spec id.
    for (const ref of adapterRefs) {
      for (const c of getAdapter(ref)!.channels) {
        expect(c.unit, `${ref}: ${c.name}`).not.toBe('kph')
        expect(c.unit, `${ref}: ${c.name}`).not.toBe('count')
      }
    }
  })
})
